"""The core's frozen value types: teams, actions, steps, transitions and run settings."""

from collections.abc import Mapping
from dataclasses import dataclass, field
from typing import Final, Literal, get_args

import numpy as np

SOLO: Final = "agents"
"""The one team name every single-team environment uses (AD-13)."""

EnvName = Literal["snake", "corridor", "tank", "predprey"]
ViewName = Literal["compact", "grid", "index", "full", "limited"]
AgentName = Literal["tabular", "dqn", "reinforce", "ppo", "random", "scripted", "reference"]
OpponentRole = Literal["learn", "scripted", "random"]
SelfPlay = Literal["none", "latest", "pool"]
Ablation = Literal["none", "no_memory", "no_target", "no_explore"]

MAX_SEED: Final = 1_000_000
MAX_EVAL_GAMES: Final = 1000
MAX_FISH: Final = 16
GENERATIONS: Final = 10
PREDPREY_TEAMS: Final = frozenset({"predator", "prey"})

_VIEWS: Final[Mapping[str, tuple[str, ...]]] = {
    "snake": ("compact", "grid"),
    "corridor": ("index",),
    "tank": ("full", "limited"),
    "predprey": ("limited",),
}
_VALUE_AGENTS: Final = ("tabular", "dqn")
_POLICY_AGENTS: Final = ("reinforce", "ppo")
_ABLATION_AGENT: Final[Mapping[str, str]] = {
    "no_memory": "dqn",
    "no_target": "dqn",
    "no_explore": "tabular",
}


@dataclass(frozen=True)
class ActionSpace:
    """A team's actions: `n` discrete choices, or a `dim`-vector the environment clips."""

    kind: Literal["discrete", "continuous"]
    n: int = 0
    dim: int = 0

    def __post_init__(self) -> None:
        if self.kind == "discrete" and (self.n < 2 or self.dim != 0):  # noqa-free: plain check
            raise ValueError(f"discrete actions need n >= 2 and dim == 0, got {self}")
        if self.kind == "continuous" and (self.dim < 1 or self.n != 0):
            raise ValueError(f"continuous actions need dim >= 1 and n == 0, got {self}")
        if self.kind not in get_args(ActionSpace.__annotations__["kind"]):
            raise ValueError(f"kind: unknown action kind {self.kind!r}")


@dataclass(frozen=True)
class TeamSpec:
    """One team: its agent count, per-agent observation shape and shared action space."""

    n_agents: int
    obs_shape: tuple[int, ...]
    actions: ActionSpace

    def __post_init__(self) -> None:
        if self.n_agents < 1:
            raise ValueError(f"n_agents: a team needs at least one agent, got {self.n_agents}")


@dataclass(frozen=True)
class StepResult:
    """One environment step, keyed by team; each team's arrays are batch-first (AD-09, AD-13)."""

    obs: dict[str, np.ndarray]
    reward: dict[str, np.ndarray]
    done: dict[str, np.ndarray]
    terminated: bool
    truncated: bool
    info: dict[str, float]

    def __post_init__(self) -> None:
        if self.terminated and self.truncated:
            raise ValueError("a step is terminated or truncated, never both")


@dataclass(frozen=True)
class Transition:
    """One learning team's step, batch-first over its agents; `active` marks who acted."""

    obs: np.ndarray
    actions: np.ndarray
    reward: np.ndarray
    next_obs: np.ndarray
    terminated: np.ndarray
    active: np.ndarray
    truncated: bool


@dataclass(frozen=True)
class Rewards:
    """Reward values: food (or the corridor goal), death (or a catch) and every step."""

    food: float = 1.0
    death: float = -1.0
    step: float = 0.0


@dataclass(frozen=True)
class Exploration:
    """A linear exploration schedule from `start` to `end` over `decay_steps` (AGENT-02)."""

    start: float = 1.0
    end: float = 0.05
    decay_steps: int = 50_000

    def __post_init__(self) -> None:
        if not 0.0 <= self.end <= self.start <= 1.0:
            raise ValueError(f"exploration: need 0 <= end <= start <= 1, got {self}")


@dataclass(frozen=True)
class AgentParams:
    """Learner hyperparameters; each agent reads the fields its contract names."""

    lr: float
    gamma: float
    batch_size: int = 64
    memory_size: int = 50_000
    target_every: int = 1_000
    learn_start: int = 1_000
    hidden: int = 128
    net: Literal["mlp", "cnn"] = "mlp"
    rollout_steps: int = 2048
    epochs: int = 10
    clip: float = 0.2
    gae_lambda: float = 0.95
    games_per_update: int = 10

    def __post_init__(self) -> None:
        if not 0.0 < self.gamma <= 1.0:
            raise ValueError(f"gamma: need 0 < gamma <= 1, got {self.gamma}")
        if self.net not in ("mlp", "cnn"):
            raise ValueError(f"net: unknown network {self.net!r}")


@dataclass(frozen=True, kw_only=True)
class RunSettings:
    """Everything one run needs, resolved from its TOML file (RUN-01, AD-06)."""

    name: str
    env: EnvName
    view: ViewName
    agent: AgentName
    n_agents: int = 1
    opponents: Mapping[str, OpponentRole] = field(default_factory=dict)
    self_play: SelfPlay = "none"
    pool_latest: float = 0.5
    generations: int = 0
    ablation: Ablation = "none"
    rewards: Rewards = field(default_factory=Rewards)
    exploration: Exploration = field(default_factory=Exploration)
    params: AgentParams
    steps: int
    seed: int = 0
    eval_every: int
    eval_games: int

    def __post_init__(self) -> None:
        _check_names(self)
        _check_ranges(self)
        _check_agent(self)
        _check_teams(self)


def _check_names(s: RunSettings) -> None:
    for key, alias in (
        ("env", EnvName),
        ("view", ViewName),
        ("agent", AgentName),
        ("self_play", SelfPlay),
        ("ablation", Ablation),
    ):
        value = getattr(s, key)
        if value not in get_args(alias):
            raise ValueError(f"{key}: unknown value {value!r}")
    if s.view not in _VIEWS[s.env]:
        raise ValueError(f"view: {s.view!r} does not belong to env {s.env!r}")


def _check_ranges(s: RunSettings) -> None:
    if not 0 <= s.seed < MAX_SEED:
        raise ValueError(f"seed: must be in [0, {MAX_SEED}), got {s.seed}")
    if s.steps <= 0:
        raise ValueError(f"steps: must be > 0, got {s.steps}")
    if s.eval_every <= 0:
        raise ValueError(f"eval_every: must be > 0, got {s.eval_every}")
    if not 1 <= s.eval_games <= MAX_EVAL_GAMES:
        raise ValueError(f"eval_games: must be in [1, {MAX_EVAL_GAMES}], got {s.eval_games}")
    if not 0.0 <= s.pool_latest <= 1.0:
        raise ValueError(f"pool_latest: must be in [0, 1], got {s.pool_latest}")
    most = MAX_FISH if s.env == "tank" else 1
    if not 1 <= s.n_agents <= most:
        raise ValueError(f"n_agents: must be in [1, {most}] for {s.env!r}, got {s.n_agents}")


def _check_agent(s: RunSettings) -> None:
    if s.agent in _POLICY_AGENTS and s.env not in ("tank", "predprey"):
        raise ValueError(f"agent: {s.agent!r} runs only on the tank")
    if s.agent in _VALUE_AGENTS and s.env not in ("snake", "corridor"):
        raise ValueError(f"agent: {s.agent!r} runs only on Snake or the corridor")
    if s.env == "tank" and s.agent == "reference" and (s.n_agents != 1 or s.view != "full"):
        raise ValueError("agent: the tank reference needs n_agents == 1 and the full view")
    if s.env == "predprey" and s.agent not in ("ppo", "reference"):
        raise ValueError(f"agent: predator-prey runs ppo or reference, got {s.agent!r}")
    needs = _ABLATION_AGENT.get(s.ablation)
    if needs is not None and s.agent != needs:
        raise ValueError(f"ablation: {s.ablation!r} needs agent {needs!r}, got {s.agent!r}")


def _check_teams(s: RunSettings) -> None:
    if s.env != "predprey":
        if s.opponents:
            raise ValueError(f"opponents: single-team runs have none, got {dict(s.opponents)}")
        if s.self_play != "none":
            raise ValueError(f"self_play: single-team runs use 'none', got {s.self_play!r}")
        return
    if set(s.opponents) != PREDPREY_TEAMS:
        raise ValueError(f"opponents: must name 'predator' and 'prey', got {dict(s.opponents)}")
    roles = set(s.opponents.values())
    if not roles <= set(get_args(OpponentRole)):
        raise ValueError(f"opponents: unknown role in {dict(s.opponents)}")
    both_learn = roles == {"learn"}
    if both_learn != (s.self_play != "none"):
        raise ValueError(f"self_play: 'latest' or 'pool' only when both teams learn, got {s.self_play!r}")
    expected = GENERATIONS if "learn" in roles else 0
    if s.generations != expected:
        raise ValueError(f"generations: must be {expected} here, got {s.generations}")

